-- >>> supabase/migrations/0003_core.sql
-- 0003_core: time, settings, errors, business days, chains, labels, role helpers, logging, notifications.

-- Time --------------------------------------------------------------------
-- demo_today (time travel) only applies when the deployment flag demo_time_travel is enabled (M9).
-- The flag lives in realisasi.deployment_flags, which no RPC writes; the demo seed enables it, production leaves it absent/false.
create function realisasi.demo_time_travel_enabled() returns boolean
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select coalesce((select f.enabled from realisasi.deployment_flags f where f.key = 'demo_time_travel'), false)
$$;

create function realisasi._demo_today() returns date
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select (s.value #>> '{}')::date from realisasi.settings s
   where s.key = 'demo_today' and jsonb_typeof(s.value) = 'string' and realisasi.demo_time_travel_enabled()
$$;

create function realisasi.today() returns date
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select coalesce(realisasi._demo_today(), (now() at time zone 'Asia/Jakarta')::date)
$$;

create function realisasi.now_ts() returns timestamptz
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select coalesce((select (d + (now() at time zone 'Asia/Jakarta')::time) at time zone 'Asia/Jakarta'
                     from realisasi._demo_today() d where d is not null), now())
$$;

-- System caller = no JWT subject AND not running as the API roles (pg_cron, seeds, psql as owner).
-- An `authenticated` connection whose claims are empty is NOT the system (M4).
create function realisasi._is_system_caller() returns boolean
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select auth.uid() is null
     and coalesce(nullif(current_setting('role', true), ''), 'none') not in ('authenticated', 'anon')
$$;

-- Settings ----------------------------------------------------------------
create function realisasi.setting_int(p_key text) returns int
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select (value #>> '{}')::numeric::int from realisasi.settings where key = p_key
$$;

create function realisasi.setting_num(p_key text) returns numeric
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select (value #>> '{}')::numeric from realisasi.settings where key = p_key
$$;

create function realisasi.settings_json() returns jsonb
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select coalesce(jsonb_object_agg(key, value order by key), '{}'::jsonb)
    from realisasi.settings where key <> 'demo_today'
$$;

-- Errors ------------------------------------------------------------------
create function realisasi._raise(p_code text, p_message text, p_detail jsonb default null) returns void
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
begin
  raise exception using errcode = 'P0001', message = p_code || ': ' || p_message,
                        detail = coalesce(p_detail::text, '');
end $$;

create function realisasi._require_uid() returns uuid
language plpgsql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare v uuid := auth.uid();
begin
  -- a Realisasi user = a SIMKS account with an active realisasi.account_roles row (kerjasama.profiles.app_role not null)
  if v is null or not exists (select 1 from kerjasama.profiles where id = v and app_role is not null) then
    perform realisasi._raise('AUTH_REQUIRED', 'Sesi tidak valid. Silakan masuk kembali.');
  end if;
  return v;
end $$;

create function realisasi._forbidden() returns void
language sql security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select realisasi._raise('AUTH_FORBIDDEN', 'Anda tidak memiliki akses untuk tindakan ini.')
$$;

create function realisasi._not_found() returns void
language sql security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select realisasi._raise('NOT_FOUND', 'Data tidak ditemukan.')
$$;

create function realisasi._state_invalid() returns void
language sql security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select realisasi._raise('STATE_INVALID', 'Tindakan tidak dapat dilakukan pada status kegiatan saat ini.')
$$;

-- Business days / SLA -----------------------------------------------------
-- closed form: weekdays in (p_from, p_to] minus weekday holidays (no per-day series; M10)
create function realisasi.business_days_between(p_from date, p_to date) returns int
language sql stable parallel safe security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select case when p_from is null or p_to is null or p_to <= p_from then 0 else (
    select (5 * (n / 7)
            + (select count(*) from generate_series(1, n % 7) k where extract(isodow from p_from + 7 * (n / 7) + k) < 6)
            - (select count(*) from realisasi.holidays h where h.day > p_from and h.day <= p_to and extract(isodow from h.day) < 6))::int
      from (select p_to - p_from as n) x) end
$$;

create function realisasi._business_days_ago(p_n int) returns date
language plpgsql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare v_today date := realisasi.today(); v_d date := realisasi.today();
begin
  while realisasi.business_days_between(v_d, v_today) < p_n loop
    v_d := v_d - 1;
  end loop;
  return v_d;
end $$;

create function realisasi.sla_days(p_since timestamptz) returns int
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select case when p_since is null then null
    else realisasi.business_days_between((p_since at time zone 'Asia/Jakarta')::date, realisasi.today()) end
$$;

create function realisasi.sla_level(p_days int) returns text
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select case when p_days is null then null
              when p_days > realisasi.setting_int('sla_red_days') then 'red'
              when p_days > realisasi.setting_int('sla_yellow_days') then 'yellow'
              else 'ok' end
$$;

-- Renewal chains (Schema §5.1) -------------------------------------------
create function realisasi.chain_root(p_doc int) returns int
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  with recursive up as (
    select id, predecessor_id, 0 as depth from kerjasama.documents where id = p_doc
    union all
    select d.id, d.predecessor_id, up.depth + 1 from kerjasama.documents d join up on d.id = up.predecessor_id
    where up.depth < 100
  )
  select id from up where predecessor_id is null limit 1
$$;

create function realisasi.chain_current(p_doc int) returns int
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  with recursive down as (
    select id, 0 as depth from kerjasama.documents where id = p_doc
    union all
    select d.id, down.depth + 1 from kerjasama.documents d join down on d.predecessor_id = down.id
    where down.depth < 100
  )
  select id from down order by depth desc, id desc limit 1
$$;

-- every document with its chain root and depth, in one recursive pass (H6; chain_root() per document is O(docs x depth))
create function realisasi._chain_map() returns table(doc_id int, root_id int, depth int)
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  with recursive m as (
    select d.id as doc_id, d.id as root_id, 0 as depth from kerjasama.documents d where d.predecessor_id is null
    union all
    select d.id, m.root_id, m.depth + 1 from kerjasama.documents d join m on d.predecessor_id = m.doc_id where m.depth < 100
  )
  select doc_id, root_id, depth from m
$$;

-- Labels ------------------------------------------------------------------
create function realisasi.semester_label(p_semester_id int) returns text
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select initcap(s.term::text) || ' ' || ay.label
    from realisasi.semesters s join realisasi.academic_years ay on ay.id = s.academic_year_id
   where s.id = p_semester_id
$$;

create function realisasi._snapshot_label(p_kind realisasi.snapshot_kind, p_ay_label text) returns text
language sql immutable set search_path = realisasi, extensions, public, pg_temp as $$
  select case p_kind when 'ganjil_ytd' then 'Ganjil ' || p_ay_label || ' (YTD)'
                     else 'Genap ' || p_ay_label || ' (Setahun)' end
$$;

create function realisasi._fmt_date(p_d date) returns text
language sql immutable set search_path = realisasi, extensions, public, pg_temp as $$
  select to_char(p_d, 'DD') || ' ' ||
         (array['Jan','Feb','Mar','Apr','Mei','Jun','Jul','Agu','Sep','Okt','Nov','Des'])[extract(month from p_d)::int]
         || ' ' || to_char(p_d, 'YYYY')
$$;

create function realisasi._profile_name(p_id uuid) returns text
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select display_name from kerjasama.profiles where id = p_id
$$;

-- Role helpers ------------------------------------------------------------
create function realisasi.my_role() returns text
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select app_role from kerjasama.profiles where id = auth.uid()
$$;

create function realisasi.my_unit() returns int
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select unit_id from kerjasama.profiles where id = auth.uid()
$$;

create function realisasi.in_team(p_team realisasi.team) returns boolean
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select coalesce(realisasi.my_role() = 'io_admin', false)
      or exists (select 1 from realisasi.team_members tm
                  join kerjasama.profiles p on p.id = tm.account_id and p.app_role in ('io_staff','io_admin')
                 where tm.account_id = auth.uid() and tm.team = p_team)
$$;

create function realisasi.is_io() returns boolean
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select coalesce(realisasi.my_role() in ('io_staff','io_admin'), false)
$$;

create function realisasi.can_view_activity(p_activity uuid) returns boolean
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select case realisasi.my_role()
    when 'io_admin' then true
    when 'io_staff' then true
    when 'viewer' then exists (select 1 from realisasi.activities a where a.id = p_activity and a.status = 'verified')
    when 'submitter' then exists (select 1 from realisasi.activity_units au
                                   where au.activity_id = p_activity and au.unit_id = realisasi.my_unit())
    else false end
$$;

create function realisasi.can_view_participants(p_activity uuid) returns boolean
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select case
    when realisasi.my_role() = 'io_admin' then true
    when realisasi.my_role() = 'io_staff' then realisasi.in_team('mobility')
    when realisasi.my_role() = 'submitter' then exists (select 1 from realisasi.activity_units au
                                   where au.activity_id = p_activity and au.unit_id = realisasi.my_unit())
    else false end
$$;

-- Set-returning helpers for RLS policies: evaluated once per statement as hashed subplans (M10)
-- activities of the caller's unit (submitter only; own + co-unit)
create function realisasi.my_activity_ids() returns setof uuid
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select au.activity_id from realisasi.activity_units au
   where au.unit_id = (select realisasi.my_unit()) and (select realisasi.my_role()) = 'submitter'
$$;

-- activities visible to a non-IO caller (viewer: verified; submitter: own + co-unit). IO is handled by is_io() in the policy.
create function realisasi.visible_activity_ids() returns setof uuid
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select a.id from realisasi.activities a where (select realisasi.my_role()) = 'viewer' and a.status = 'verified'
  union all
  select realisasi.my_activity_ids()
$$;

-- participant set versions whose rows a submitter may read
create function realisasi.my_pset_ids() returns setof uuid
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select v.id from realisasi.participant_set_versions v where v.activity_id in (select realisasi.my_activity_ids())
$$;

-- caller may read participant identifiers of every activity they can see (io_admin, mobility team, submitters for own/co-unit)
create function realisasi.sees_participant_identifiers() returns boolean
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select coalesce(realisasi.my_role() in ('io_admin','submitter'), false) or realisasi.in_team('mobility')
$$;

-- participant identifiers in log diffs replaced by counts (M6: Partnership/viewers see counts only)
create function realisasi._mask_log_diff(p jsonb) returns jsonb
language sql immutable set search_path = realisasi, extensions, public, pg_temp as $$
  select case when p is null or jsonb_typeof(p) <> 'object' then p else
    (p - 'students' - 'staff' - 'row_notes')
    || case when jsonb_typeof(p -> 'students') = 'object' then jsonb_build_object('students', jsonb_build_object(
           'added', coalesce(jsonb_array_length(nullif(p -> 'students' -> 'added', 'null')), 0),
           'removed', coalesce(jsonb_array_length(nullif(p -> 'students' -> 'removed', 'null')), 0))) else '{}'::jsonb end
    || case when jsonb_typeof(p -> 'staff') = 'object' then jsonb_build_object('staff', jsonb_build_object(
           'added', coalesce(jsonb_array_length(nullif(p -> 'staff' -> 'added', 'null')), 0),
           'removed', coalesce(jsonb_array_length(nullif(p -> 'staff' -> 'removed', 'null')), 0))) else '{}'::jsonb end
    || case when jsonb_typeof(p -> 'row_notes') = 'array' then jsonb_build_object('row_notes', jsonb_array_length(p -> 'row_notes')) else '{}'::jsonb end
  end
$$;

-- participant set version that counted for an activity at p_as_of (M2): the latest approved/superseded version
-- reviewed (approved) by then; falls back to the current approved version. p_as_of null = current approved.
create function realisasi._pset_as_of(p_activity uuid, p_as_of timestamptz) returns uuid
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select coalesce(
    (select v.id from realisasi.participant_set_versions v
      where p_as_of is not null and v.activity_id = p_activity and v.status in ('approved','superseded')
        and v.reviewed_at is not null and v.reviewed_at <= p_as_of
      order by v.version desc limit 1),
    (select v.id from realisasi.participant_set_versions v where v.activity_id = p_activity and v.status = 'approved'))
$$;

create function realisasi._is_unit_editor(p_activity uuid) returns boolean
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select coalesce(realisasi.my_role() = 'io_admin', false)
      or (coalesce(realisasi.my_role() = 'submitter', false)
          and exists (select 1 from realisasi.activities a
                       where a.id = p_activity and a.submitter_unit_id = realisasi.my_unit()))
$$;

create function realisasi.in_frozen_period(p_activity uuid) returns boolean
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select exists (select 1 from realisasi.activities a
                   join realisasi.kpi_snapshots s on s.superseded_by is null
                    and a.start_date between s.window_start and s.window_end
                  where a.id = p_activity)
$$;

create function realisasi.is_late_addition(p_activity uuid) returns boolean
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select exists (select 1 from realisasi.activities a
                   join realisasi.kpi_snapshots s on s.superseded_by is null
                    and a.start_date between s.window_start and s.window_end
                  where a.id = p_activity and a.status = 'verified' and a.verified_at > s.frozen_at)
$$;

-- Permission predicates shared by RPCs and activity_detail.permissions (internal)
-- participant-edit permission (CONTRACTS §3.2 ensure_participant_draft)
create function realisasi._can_edit_participants(p_activity uuid, p_include_io boolean default true) returns boolean
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select exists (select 1 from realisasi.activities a where a.id = p_activity and (
           (realisasi._is_unit_editor(a.id) and a.status <> 'rejected'
             and (a.status = 'draft' or a.mobility_status = 'revision_requested' or a.partnership_status = 'revision_requested'))
        or (p_include_io and a.status = 'verified' and realisasi.in_team('mobility'))))
$$;

-- file write permission (CONTRACTS §3.3)
create function realisasi._can_write_files(p_activity uuid) returns boolean
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select exists (select 1 from realisasi.activities a where a.id = p_activity and (
           (realisasi._is_unit_editor(a.id) and (a.status = 'draft' or a.partnership_status = 'revision_requested'))
        or (a.status = 'verified' and realisasi.in_team('partnership'))))
$$;

-- View helpers (definer, counts only; granted so security_invoker views can call them)
create function realisasi.activity_linked_count(p_activity uuid) returns int
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select count(*)::int from realisasi.activities o
    join realisasi.activities a on a.id = p_activity and o.event_group_id = a.event_group_id and o.id <> a.id
$$;

create function realisasi.activity_participant_total(p_activity uuid) returns int
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select coalesce((select (select count(*) from realisasi.participant_students s where s.set_version_id = v.id)
                        + (select count(*) from realisasi.participant_staff st where st.set_version_id = v.id)
                     from realisasi.participant_set_versions v
                    where v.activity_id = p_activity and v.status <> 'draft'
                    order by v.version desc limit 1), 0)::int
$$;

-- Logging -----------------------------------------------------------------
create function realisasi._log(p_activity uuid, p_kind realisasi.log_kind, p_track realisasi.team, p_action text,
                               p_note text default null, p_diff jsonb default null) returns bigint
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare v_id bigint;
begin
  insert into realisasi.activity_log (activity_id, kind, track, action, actor_id, note, diff, in_frozen_period, created_at)
  values (p_activity, p_kind, p_track, p_action, auth.uid(), p_note, p_diff,
          case when p_kind = 'update' then realisasi.in_frozen_period(p_activity) else false end,
          realisasi.now_ts())
  returning id into v_id;
  return v_id;
end $$;

-- Notifications -------------------------------------------------------------
create function realisasi._notify(p_recipient uuid, p_kind text, p_title text, p_body text, p_link text) returns void
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare v_email text;
begin
  select email into v_email from kerjasama.profiles where id = p_recipient and app_role is not null;
  if v_email is null then return; end if;
  insert into realisasi.notifications (recipient_id, kind, title, body, link, created_at)
  values (p_recipient, p_kind, p_title, p_body, p_link, realisasi.now_ts());
  insert into realisasi.email_outbox (to_email, subject, body, created_at)
  values (v_email, p_title, coalesce(p_body, '') || E'\n\n' || coalesce(p_link, ''), realisasi.now_ts());
end $$;

create function realisasi._notify_many(p_recipients uuid[], p_kind text, p_title text, p_body text, p_link text) returns int
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare r uuid; n int := 0;
begin
  for r in select distinct x from unnest(p_recipients) x where x is not null order by 1 loop
    perform realisasi._notify(r, p_kind, p_title, p_body, p_link);
    n := n + 1;
  end loop;
  return n;
end $$;

create function realisasi._team_ids(p_team realisasi.team) returns uuid[]
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select coalesce(array_agg(distinct tm.account_id), '{}') from realisasi.team_members tm where tm.team = p_team
$$;

create function realisasi._admin_ids() returns uuid[]
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select coalesce(array_agg(id order by id), '{}') from kerjasama.profiles where app_role = 'io_admin'
$$;

create function realisasi._notify_team(p_team realisasi.team, p_kind text, p_title text, p_body text, p_link text) returns void
language sql security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select realisasi._notify_many(realisasi._team_ids(p_team), p_kind, p_title, p_body, p_link);
  select null::void
$$;

-- team notification minus the members of another team already notified for the same event (requirements-review L-4)
create function realisasi._notify_team_except(p_team realisasi.team, p_except realisasi.team, p_kind text, p_title text, p_body text, p_link text) returns void
language sql security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select realisasi._notify_many(array(select unnest(realisasi._team_ids(p_team)) except select unnest(realisasi._team_ids(p_except))),
                                p_kind, p_title, p_body, p_link);
  select null::void
$$;

create function realisasi._notify_admins(p_kind text, p_title text, p_body text, p_link text) returns void
language sql security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select realisasi._notify_many(realisasi._admin_ids(), p_kind, p_title, p_body, p_link);
  select null::void
$$;

create function realisasi._notify_unit(p_unit_id int, p_kind text, p_title text, p_body text, p_link text) returns void
language sql security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select realisasi._notify_many((select coalesce(array_agg(id), '{}') from kerjasama.profiles
                                  where app_role = 'submitter' and unit_id = p_unit_id),
                                p_kind, p_title, p_body, p_link);
  select null::void
$$;

create function realisasi._notify_viewers(p_kind text, p_title text, p_body text, p_link text) returns void
language sql security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select realisasi._notify_many((select coalesce(array_agg(id), '{}') from kerjasama.profiles where app_role = 'viewer'),
                                p_kind, p_title, p_body, p_link);
  select null::void
$$;

-- >>> supabase/migrations/0004_views.sql
-- 0004_views (CONTRACTS §2.7). All security_invoker except v_chains (public data only).

create view realisasi.v_activity_documents with (security_invoker = true) as
select ad.activity_id, ad.original_document_id, ad.chain_id, ad.out_of_scope_warning,
       realisasi.chain_current(ad.original_document_id) as current_document_id,
       od.doc_number as original_doc_number,
       cd.doc_number as current_doc_number
  from realisasi.activity_documents ad
  join kerjasama.documents od on od.id = ad.original_document_id
  left join kerjasama.documents cd on cd.id = realisasi.chain_current(ad.original_document_id);

-- v_chains: one row per renewal chain. Chain membership comes from one recursive pass (_chain_map; H6).
-- auto_renewed / terminated_at describe the chain's CURRENT valid document (deepest non in_process/rejected document),
-- so a terminated or replaced auto-renewed agreement stops being open-ended (H2). terminated_at is an additive column.
create view realisasi.v_chains as
with m as (
  select * from realisasi._chain_map()
), docs as (
  select d.*, m.root_id as chain_id, m.depth
    from kerjasama.documents d join m on m.doc_id = d.id
   where d.start_date is not null and d.status not in ('in_process','rejected')
), agg as (
  select chain_id,
         min(start_date) as chain_start,
         max(coalesce(terminated_at::date, end_date)) as chain_end,
         (array_agg(auto_renewed order by depth desc, id desc))[1] as auto_renewed,
         (array_agg(terminated_at order by depth desc, id desc))[1] as terminated_at,
         array_agg(id order by start_date, id) as document_ids,
         array_agg(doc_number order by start_date, id) as doc_numbers
    from docs group by chain_id
), cur as (                                   -- = chain_current(root): deepest document of any status
  select distinct on (root_id) root_id, doc_id from m order by root_id, depth desc, doc_id desc
), prt as (
  select dc.chain_id, bool_or(p.country_code <> 'ID') as is_international,
         array_agg(distinct p.name order by p.name) as partner_names,
         array_agg(distinct p.country_code order by p.country_code) as country_codes
    from docs dc join kerjasama.document_partners dp on dp.document_id = dc.id join kerjasama.partners p on p.id = dp.partner_id
   group by dc.chain_id
)
select a.chain_id, a.chain_start, a.chain_end, a.auto_renewed,
       coalesce(prt.is_international, false) as is_international,
       a.document_ids, a.doc_numbers,
       cd.id as current_document_id, cd.doc_number as current_doc_number, cd.kind, cd.title,
       coalesce(prt.partner_names, '{}') as partner_names,
       coalesce(prt.country_codes, '{}') as country_codes,
       a.terminated_at
  from agg a
  left join cur on cur.root_id = a.chain_id
  left join kerjasama.documents cd on cd.id = cur.doc_id
  left join prt on prt.chain_id = a.chain_id;

create view realisasi.v_activity_list with (security_invoker = true) as
select a.id, a.code, a.name, a.type_id, t.name as type_name, t.direction,
       a.start_date, a.end_date, a.academic_year_id, ay.label as ay_label,
       a.semester_id, case when s.id is null then null else initcap(s.term::text) || ' ' || ay.label end as semester_label,
       a.mode, a.status, a.partnership_status, a.mobility_status, a.partnership_since, a.mobility_since,
       sla.p_days as partnership_sla_days, realisasi.sla_level(sla.p_days) as partnership_sla_level,
       sla.m_days as mobility_sla_days, realisasi.sla_level(sla.m_days) as mobility_sla_level,
       a.submitter_unit_id, su.name as submitter_unit_name,
       coalesce(u.unit_ids, '{}') as unit_ids, coalesce(u.unit_names, '{}') as unit_names,
       coalesce(d.document_ids, '{}') as document_ids, coalesce(d.document_numbers, '{}') as document_numbers,
       coalesce(d.chain_ids, '{}') as chain_ids,
       coalesce(ps.partner_names, '{}') as partner_names, coalesce(ps.country_codes, '{}') as country_codes,
       coalesce(ps.is_international, false) as is_international,
       a.is_late, a.reporting_deadline, a.submitted_at, a.verified_at,
       a.created_at, a.updated_at, a.created_by,
       coalesce(d.out_of_scope, false) as out_of_scope,
       exists (select 1 from realisasi.duplicate_candidates dc
                where dc.status = 'open' and (dc.activity_a = a.id or dc.activity_b = a.id)) as duplicate_open,
       a.event_group_id, realisasi.activity_linked_count(a.id) as linked_count
  from realisasi.activities a
  join realisasi.activity_types t on t.id = a.type_id
  left join realisasi.academic_years ay on ay.id = a.academic_year_id
  left join realisasi.semesters s on s.id = a.semester_id
  left join kerjasama.units su on su.id = a.submitter_unit_id
  cross join lateral (
    select case when a.partnership_status = 'pending' and a.status not in ('draft','rejected')
                then realisasi.sla_days(a.partnership_since) end as p_days,
           case when a.mobility_status = 'pending' and a.status not in ('draft','rejected')
                then realisasi.sla_days(a.mobility_since) end as m_days) sla
  left join lateral (
    select array_agg(au.unit_id order by au.is_submitter desc, un.name) as unit_ids,
           array_agg(un.name order by au.is_submitter desc, un.name) as unit_names
      from realisasi.activity_units au join kerjasama.units un on un.id = au.unit_id
     where au.activity_id = a.id) u on true
  left join lateral (
    select array_agg(ad.original_document_id order by doc.doc_number) as document_ids,
           array_agg(doc.doc_number order by doc.doc_number) as document_numbers,
           array_agg(distinct ad.chain_id) as chain_ids,
           bool_or(ad.out_of_scope_warning) as out_of_scope
      from realisasi.activity_documents ad join kerjasama.documents doc on doc.id = ad.original_document_id
     where ad.activity_id = a.id) d on true
  left join lateral (
    select array_agg(distinct p.partner_name) as partner_names,
           array_agg(distinct p.country_code) as country_codes,
           bool_or(p.country_code <> 'ID') as is_international
      from realisasi.activity_partner_snapshot p where p.activity_id = a.id) ps on true;

create view realisasi.v_known_activities with (security_invoker = true) as
select k.*, u.name as unit_name, c.name as country_name,
       ma.code as matched_activity_code, ma.name as matched_activity_name,
       cp.display_name as created_by_name,
       (k.unit_id is not null and k.status = 'unmatched'
        and (k.nudged_at is null
             or k.nudged_at < realisasi.now_ts() - make_interval(days => realisasi.setting_int('nudge_resend_days')))) as can_nudge
  from realisasi.known_activities k
  left join kerjasama.units u on u.id = k.unit_id
  left join kerjasama.countries c on c.code = k.country_code
  left join realisasi.activities ma on ma.id = k.matched_activity_id
  left join kerjasama.profiles cp on cp.id = k.created_by;

create view realisasi.v_duplicate_candidates with (security_invoker = true) as
select dc.id, dc.score, dc.status, rp.display_name as resolved_by_name, dc.resolved_at,
       a.id as a_id, a.code as a_code, a.name as a_name, au.name as a_unit_name,
       a.start_date as a_start_date, a.end_date as a_end_date, a.status as a_status,
       coalesce((select array_agg(d.doc_number order by d.doc_number) from realisasi.activity_documents ad
                   join kerjasama.documents d on d.id = ad.original_document_id where ad.activity_id = a.id), '{}') as a_documents,
       realisasi.activity_participant_total(a.id) as a_participants,
       b.id as b_id, b.code as b_code, b.name as b_name, bu.name as b_unit_name,
       b.start_date as b_start_date, b.end_date as b_end_date, b.status as b_status,
       coalesce((select array_agg(d.doc_number order by d.doc_number) from realisasi.activity_documents ad
                   join kerjasama.documents d on d.id = ad.original_document_id where ad.activity_id = b.id), '{}') as b_documents,
       realisasi.activity_participant_total(b.id) as b_participants
  from realisasi.duplicate_candidates dc
  join realisasi.activities a on a.id = dc.activity_a
  join realisasi.activities b on b.id = dc.activity_b
  left join kerjasama.units au on au.id = a.submitter_unit_id
  left join kerjasama.units bu on bu.id = b.submitter_unit_id
  left join kerjasama.profiles rp on rp.id = dc.resolved_by;

-- >>> supabase/migrations/0005_triggers.sql
-- 0005_triggers (CONTRACTS §2.6)

-- Period derivation: academic year + semester from start_date (NULL when outside the calendar; R-09 at submit)
create function realisasi._trg_derive_period() returns trigger
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
begin
  select ay.id into new.academic_year_id from realisasi.academic_years ay
   where new.start_date between ay.start_date and ay.end_date order by ay.start_date limit 1;
  select s.id into new.semester_id from realisasi.semesters s
   where new.start_date between s.start_date and s.end_date order by s.start_date limit 1;
  if not found then new.semester_id := null; end if;
  return new;
end $$;
create trigger trg_activities_derive_period
  before insert or update of start_date on realisasi.activities
  for each row execute function realisasi._trg_derive_period();

-- Reporting deadline + lateness (R-10)
create function realisasi._trg_derive_deadline() returns trigger
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
begin
  new.reporting_deadline := new.end_date + coalesce(realisasi.setting_int('reporting_deadline_days'), 30);
  new.is_late := new.submitted_at is not null
                 and (new.submitted_at at time zone 'Asia/Jakarta')::date > new.reporting_deadline;
  return new;
end $$;
create trigger trg_activities_derive_deadline
  before insert or update of end_date, submitted_at on realisasi.activities
  for each row execute function realisasi._trg_derive_deadline();

-- Overall status (R-25), verified_at (R-28), track clocks
create function realisasi._trg_activity_status() returns trigger
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
begin
  new.status := case
    when new.submitted_at is null then 'draft'
    when new.partnership_status = 'rejected' then 'rejected'
    when new.partnership_status = 'revision_requested' or new.mobility_status = 'revision_requested' then 'revision_requested'
    when new.partnership_status = 'approved' and new.mobility_status in ('approved','not_required') then 'verified'
    else 'in_verification' end::realisasi.activity_status;

  if tg_op = 'UPDATE' and old.verified_at is not null then
    new.verified_at := old.verified_at;                       -- R-28: never cleared / changed
  elsif new.status = 'verified' and new.verified_at is null then
    new.verified_at := realisasi.now_ts();
  end if;

  if tg_op = 'INSERT' then
    new.partnership_since := coalesce(new.partnership_since, realisasi.now_ts());
    new.mobility_since    := coalesce(new.mobility_since, realisasi.now_ts());
  else
    if new.partnership_status is distinct from old.partnership_status
       and new.partnership_since is not distinct from old.partnership_since then
      new.partnership_since := realisasi.now_ts();
    end if;
    if new.mobility_status is distinct from old.mobility_status
       and new.mobility_since is not distinct from old.mobility_since then
      new.mobility_since := realisasi.now_ts();
    end if;
  end if;
  new.updated_at := now();
  return new;
end $$;
create trigger trg_activities_status
  before insert or update on realisasi.activities
  for each row execute function realisasi._trg_activity_status();

-- Agreement link: chain id + partner snapshot (R-03, R-06)
create function realisasi._trg_activity_documents_chain() returns trigger
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
begin
  new.chain_id := realisasi.chain_root(new.original_document_id);
  -- replaces the former FK to the SIMKS documents (kerjasama.documents is a view and cannot be an FK target)
  if new.chain_id is null then
    raise exception using errcode = '23503',
      message = format('activity_documents.original_document_id %s is not in kerjasama.documents', new.original_document_id);
  end if;
  return new;
end $$;
create trigger trg_activity_documents_snapshot
  before insert on realisasi.activity_documents
  for each row execute function realisasi._trg_activity_documents_chain();

create function realisasi._trg_activity_documents_partners() returns trigger
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
begin
  if tg_op = 'INSERT' then
    insert into realisasi.activity_partner_snapshot (activity_id, document_id, partner_id, partner_name, country_code, captured_at)
    select new.activity_id, new.original_document_id, p.id, p.name, p.country_code, realisasi.now_ts()
      from kerjasama.document_partners dp join kerjasama.partners p on p.id = dp.partner_id
     where dp.document_id = new.original_document_id
       and p.country_code is not null      -- SIMKS partner without a mappable country (kerjasama.partners)
     order by dp.is_lead desc, p.id;
    return new;
  else
    delete from realisasi.activity_partner_snapshot
     where activity_id = old.activity_id and document_id = old.original_document_id;
    return old;
  end if;
end $$;
create trigger trg_activity_documents_snapshot_after
  after insert or delete on realisasi.activity_documents
  for each row execute function realisasi._trg_activity_documents_partners();

-- Participant versions: approving a version supersedes the previous approved one (R-21)
create function realisasi._trg_pset_supersede() returns trigger
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
begin
  if new.status = 'approved' and old.status is distinct from 'approved' then
    update realisasi.participant_set_versions
       set status = 'superseded'
     where activity_id = new.activity_id and status = 'approved' and id <> new.id;
  end if;
  return new;
end $$;
create trigger trg_pset_supersede
  before update of status on realisasi.participant_set_versions
  for each row execute function realisasi._trg_pset_supersede();

-- settings.updated_at
create function realisasi._trg_touch_updated_at() returns trigger
language plpgsql set search_path = realisasi, extensions, public, pg_temp as $$
begin
  new.updated_at := now();
  return new;
end $$;
create trigger trg_touch_updated_at
  before insert or update on realisasi.settings
  for each row execute function realisasi._trg_touch_updated_at();

